        catch (FileNotFoundException f) {
            /* oh well */
        }
        catch (IOException e) {
        }

        /* Make this component depend on the APIs it imports.
         * For now, calling nodeDependsOnApi when linking will
         * also make this component depend on a component with the same name as
         * the API it imports.
         */
}

