        return ExprFactory.makeFloatLiteralExpr(S, s);
    }

    private static Expr infix(String op, Expr a, Expr b) {
        return ExprFactory.makeOpExpr(S, NodeFactory.makeOpInfix(S, op), a, b);
    }

